import{z as o,x as A,o as E,c as d,q as i,j as B,D as r,d as e,s as n,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Shamir 秘密共享","description":"","frontmatter":{"title":"Shamir 秘密共享","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shamir-secret-sharing.md","filePath":"cs/shamir-secret-sharing.md","lastUpdated":1791413859000}'),h={name:"cs/shamir-secret-sharing.md"};function m(p,a,D,c,C,S){const s=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=i('<h1 id="shamir-秘密共享" tabindex="-1">Shamir 秘密共享 <a class="header-anchor" href="#shamir-秘密共享" aria-label="Permalink to &quot;Shamir 秘密共享&quot;">​</a></h1><div class="epigraph"><p>把秘密当成多项式在 0 处的值，发给每人一个点；$t$ 个点能插值，$t-1$ 个点在信息论上什么都不知道。阈值由多项式次数决定。</p><footer>—— Shamir, How to Share a Secret, Communications of the ACM, 1979</footer></div><p>上一课<a href="/cs/commitment-merkle-tree">承诺与 Merkle</a>把一个值绑进公开根。缺口是<strong>不公开、但要多人共管</strong>：任何少于阈值的集合不应得到秘密。HSM 备份常走这条，而不是把根钥复印 n 份。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把密钥切成 n 段明文，任何一段都可能泄漏部分比特。Shamir：在有限域上随机 \\(t-1\\) 次多项式，\\(f(0)=s\\)，份额是 \\((i,f(i))\\)。完善保密：少于 \\(t\\) 个点时 \\(s\\) 仍均匀。缺口是阈值方案，不是再讲 HKDF。</p><h3 id="份额也是密钥材料" tabindex="-1">份额也是密钥材料 <a class="header-anchor" href="#份额也是密钥材料" aria-label="Permalink to &quot;份额也是密钥材料&quot;">​</a></h3><p>存份额的主机被全拿仍达阈值。分发信道要保密且认证，否则份额被换（主动敌手）。</p><p><span class="marginnote">Shamir 1979。Feldman/Pedersen 可验证共享防经销商作恶，本课点名，细节留给 MPC。不要与「把文件 zip 分卷」混淆。</span></p><p><span class="marginnote">直觉类比：次数 1 的多项式是条直线——两点定线、一点不定。秘密 \\(s\\) 就是直线与 \\(y\\) 轴的交点 \\(f(0)\\)；每人拿走线上一个点，手里只有一个点时，那条线可以在平面上「晃来晃去」，交点有无穷多种可能，等于什么都不知道。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用次数 1 的直线在黑板上点名「两点定线、一点不定」。推广到 \\(t\\)。指出重构是拉格朗日插值，实现要在域上算，并防份额编号重复。</p><p><span class="marginnote">数字实例：\\(t=3, n=5\\) 时随机取二次式 \\(f(x)=s+ax+bx^2\\)，5 位托管人各拿一个点；任何 3 人到齐即可插值出 \\(s\\)，2 人凑一起对 \\(s\\) 的知识与瞎猜无异。运算要在有限域上做（如大素数域 GF(p)），在普通整数上算会让「点」退化解密。</span></p>',13)),(E(),B(l,null,{default:r(()=>[n(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%A7%98%E5%AF%86%20s%3Df(0)%22%5D%20--%3E%20POLY%5B%22%E9%9A%8F%E6%9C%BA%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20POLY%20--%3E%20SH%5B%22n%20%E4%BB%BD%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20SH%20--%3E%20T%5B%22%E4%BB%BB%E6%84%8F%20t%20%E4%BB%BD%E5%8F%AF%E9%87%8D%E6%9E%84%22%5D%0A%20%20SH%20--%3E%20LT%5B%22%E5%B0%91%E4%BA%8E%20t%20%E4%BB%BD%E6%97%A0%E4%BF%A1%E6%81%AF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("信息论安全的拆分服务托管与灾难恢复。它不提供计算：份额持有人如何"),t("strong",null,"一起签名还不重构明文私钥"),e("，是下一课门限与 MPC。重构后的 \\(s\\) 又回到单点，策略上应在 HSM 内完成重构。")],-1)),(E(),B(l,null,{default:r(()=>[n(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%94%B6%E9%9B%86%E5%88%B0%20k%20%E4%BB%BD%E4%BB%BD%E9%A2%9D%22%5D%20--%3E%20Q%7B%22k%20%5Clt%20%E9%98%88%E5%80%BC%20t%20%3F%22%7D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20NO%5B%22%E4%BF%A1%E6%81%AF%E8%AE%BA%E4%B8%8A%E9%9B%B6%E6%B3%84%E9%9C%B2%2C%20%E6%B5%81%E7%A8%8B%E7%BB%88%E6%AD%A2%22%5D%0A%20%20Q%20--%3E%7C%E5%90%A6%7C%20V%7B%22%E6%AF%8F%E4%BB%BD%E9%83%BD%E9%AA%8C%E8%AF%81%E8%BF%87%E6%9D%A5%E6%BA%90%3F%22%7D%0A%20%20V%20--%3E%7C%E5%90%A6%7C%20REJ%5B%22%E5%8F%AF%E8%83%BD%E6%B7%B7%E5%85%A5%E5%81%87%E4%BB%BD%E9%A2%9D%2C%20%E6%8B%92%E7%BB%9D%E9%87%8D%E6%9E%84%22%5D%0A%20%20V%20--%3E%7C%E6%98%AF%7C%20L%5B%22%E6%8B%89%E6%A0%BC%E6%9C%97%E6%97%A5%E6%8F%92%E5%80%BC%E6%B1%82%20f(0)%22%5D%0A%20%20L%20--%3E%20H%5B%22%E5%9C%A8%20HSM%20%E5%86%85%E5%BE%97%E5%88%B0%20s%2C%20%E4%B8%8D%E5%87%BA%E5%AE%89%E5%85%A8%E8%BE%B9%E7%95%8C%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">常见误区：初学者容易把它当成「文件加密分卷」。zip 分卷少一卷只是打不开，剩下的卷并没有什么「保密性」保证；Shamir 的「少于阈值零信息」是信息论级别的——攻击者有无限算力，也推不出关于 \\(s\\) 的任何一个比特。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写主动攻击下的份额注入步骤。下一课门限签名与 MPC 直觉：计算发生在秘密共享之上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>承诺藏一个值；共享把值拆给多人。</li><li>Shamir：\\(t\\) 点重构，\\(t-1\\) 无信息。</li><li>份额信道要保密认证；重构点仍是 TCB。</li><li>下一课：门限签名与 MPC。</li><li>出处：Shamir, 1979；对照 Stinson 的密码学教材章节。</li></ul>',5))])}const _=o(h,[["render",m]]);export{u as __pageData,_ as default};
